import json
from pathlib import Path


def summarize(rows):
    return {"settled_ids": [r["id"] for r in rows],
            "totals_minor": {"USD": sum(int(float(r["amount"]) * 100) for r in rows)}}


if __name__ == "__main__":
    Path("result.json").write_text(json.dumps(summarize(json.loads(Path("orders.json").read_text()))))
